DIR;BIT JFIRE ;* LAY A BOMB !BPL NOLAY;JSR BOMB  ;* START ONE IF YOU CAN;NOLAY;BIT JLEFTBPL NLEFT;LDA DIRAND #$0CBEQ BROUN3;INC MANYDEC MANX;BROUN3;LDX #1STX DIR    ;* 1 - LEFTSTX GOING;DEXSTX XPIXSTX RUSTIC;LDX MANXSTX CHKX;LDY MANYSTY CHKY;GETOUT     ;* AN EXIT POINT;RTS;NLEFT;BIT JRIGHTBPL NRIGHT;INC MANX;LDA DIRAND #$0CBEQ BROUN4;DEC MANXINC MANY;BROUN4;LDX #3STX XPIX;DEXSTX DIR     ;* 2 - RIGHT;DEXSTX RUSTICSTX GOING;LDY MANYSTY CHKY;LDX MANXINXSTX CHKX;RTS;NRIGHT;BIT JUP ;* UP ?BPL NUP;LDA DIRAND #$03BEQ BROUND;INC MANXDEC MANY;BROUND;LDA #4STA DIR     ;* 4 - UP;LDX #1STX GOING;DEXSTX RUSTICSTX YPIX;LDX MANXSTX CHKX;LDY MANYSTY CHKY;RTS;NUP;BIT JDOWN  ;* DOWN ?BPL GETOUT;LDA DIRAND #$03BEQ BROUN2;DEC MANYINC MANX;BROUN2;LDA #8     ;* 8 = DOWNSTA DIR;LDA #3STA YPIX;LDA #1STA GOINGSTA RUSTIC;INC MANY;LDX MANXSTX CHKX;LDY MANYINYSTY CHKY;RTS;;-------------------------------;UPPIXE;LDA GOINGBEQ SIT;LDA RUSTICBEQ KILL;LDA #0STA RUSTIC;SIT;RTS;KILL;LDA #1BIT DIRBNE MVELFT;ASL A        ; ACC = 2BIT DIRBNE MVERIT;ASL A        ; ACC = 4BIT DIRBNE MVEUP;ASL A        ; ACC = 8BIT DIRBNE MVEDWN;; SHOULD NEVER GET HERE !;MVELFT;INC XPIXLDA XPIXTAYAND #3STA XPIX;CPY #4BEQ STOPL;RTS;STOPL;LDA #0STA XPIXSTA GOING;DEC MANX;RTS;MVERIT;DEC XPIXLDA XPIXTAYAND #3STA XPIX;CPY #$FFBEQ STOPR;RTS;STOPR;LDA #0STA XPIXSTA YPIXSTA GOING;RTS;MVEDWN;DEC YPIXLDA YPIXTAY;AND #3STA YPIX;CPY #$FFBEQ STOPR;RTS;MVEUP;INC YPIXLDA YPIXTAY;AND #3STA YPIX;CPY #4BEQ STOPU;RTS;STOPU;LDA #0STA YPIXSTA GOING;DEC MANY;RTS;;-------------------------------;; RUB OUT ALL ALIEN (SL) MUST;; POINT TO TL-2;BUGRUB;LDX #13   ;* TO GET RID OF BUG!;RUUB1;LDY YRUB,X;LDA (SL),Y;CMP #148+48BCS DNTRUB;CMP #148BCS DORBUT;CMP #32BCS DNTRUB;